CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('USER','VOLUNTEER','ORGANIZATION','ADMIN');
CREATE TYPE request_status AS ENUM ('OPEN','ACCEPTED','VOLUNTEER_ASSIGNED','IN_PROGRESS','RESOLVED','CANCELLED');
CREATE TYPE urgency_level AS ENUM ('NORMAL','URGENT','CRITICAL');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(100) NOT NULL,email varchar(255) UNIQUE NOT NULL,password_hash text NOT NULL,role user_role NOT NULL DEFAULT 'USER',email_verified boolean NOT NULL DEFAULT false,blocked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),name varchar(160) NOT NULL,verified_at timestamptz,public_area varchar(120),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE volunteers (user_id uuid PRIMARY KEY REFERENCES users(id),skills text[] NOT NULL DEFAULT '{}',areas text[] NOT NULL DEFAULT '{}',available boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE disaster_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(160) NOT NULL,status varchar(20) NOT NULL CHECK(status IN('DRAFT','ACTIVE','CLOSED')),affected_areas text[] NOT NULL DEFAULT '{}',starts_at timestamptz NOT NULL,ends_at timestamptz,created_by uuid REFERENCES users(id));
CREATE TABLE help_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),public_id varchar(24) UNIQUE NOT NULL,requester_id uuid NOT NULL REFERENCES users(id),accepted_by uuid REFERENCES users(id),disaster_event_id uuid REFERENCES disaster_events(id),category varchar(20) NOT NULL,public_area varchar(120) NOT NULL,protected_location text,protected_contact text,approx_lat numeric(9,6),approx_lng numeric(9,6),people_count integer NOT NULL CHECK(people_count>0),description varchar(1000) NOT NULL,urgency urgency_level NOT NULL,status request_status NOT NULL DEFAULT 'OPEN',contact_method varchar(20) NOT NULL,image_key text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX help_requests_search_idx ON help_requests(disaster_event_id,status,urgency,category,public_area,created_at DESC);
CREATE TABLE request_status_history (id bigserial PRIMARY KEY,request_id uuid NOT NULL REFERENCES help_requests(id) ON DELETE CASCADE,status request_status NOT NULL,changed_by uuid REFERENCES users(id),note varchar(500),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE request_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES help_requests(id),volunteer_id uuid NOT NULL REFERENCES users(id),organization_id uuid REFERENCES organizations(id),active boolean NOT NULL DEFAULT true,assigned_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz); CREATE UNIQUE INDEX one_active_assignment ON request_assignments(request_id) WHERE active;
CREATE TABLE request_updates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES help_requests(id),author_id uuid NOT NULL REFERENCES users(id),body varchar(500) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),disaster_event_id uuid REFERENCES disaster_events(id),name varchar(120) NOT NULL,category varchar(30) NOT NULL,quantity integer NOT NULL CHECK(quantity>=0),unit varchar(30) NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resource_transactions (id bigserial PRIMARY KEY,resource_id uuid NOT NULL REFERENCES resources(id),quantity_delta integer NOT NULL,note varchar(250) NOT NULL,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),title varchar(120) NOT NULL,body varchar(500) NOT NULL,type varchar(40) NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX notifications_user_idx ON notifications(user_id,created_at DESC);
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES help_requests(id),reporter_id uuid NOT NULL REFERENCES users(id),reason varchar(500) NOT NULL,status varchar(20) NOT NULL DEFAULT 'PENDING',reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigserial PRIMARY KEY,actor_id uuid REFERENCES users(id),action varchar(80) NOT NULL,entity_type varchar(50),entity_id text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
